function lazyLoad(e){e.forEach(e=>{e.hasAttribute("data-src")&&(e.src=e.getAttribute("data-src"),e.removeAttribute("data-src"),e.addEventListener("load",()=>e.classList.add("loaded")))})}document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".lazy");if("IntersectionObserver"in window){const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(lazyLoad([e.target]),t.unobserve(e.target))})},{rootMargin:"200px 0px"});e.forEach(e=>t.observe(e))}else lazyLoad(e)});